INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich für IT-Probleme immer nur Google nutzen sollte?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Quellen wie Foren oder Docs sinnvoll"}, {"text": "Ja", "correct": false, "because": "Vielfalt ist besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft mir, schnell Netzwerkinfos zu sammeln?', 3, '[{"text": "Wireshark", "correct": true, "because": "Analysiert Pakete"}, {"text": "Notepad", "correct": false, "because": "Nur Text"}, {"text": "Browser", "correct": false, "because": "Kein Netzwerktool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden sind für IT-Recherchen nützlich?', 5, '[{"text": "Online-Dokumentation", "correct": true, "because": "Offizielle Quellen"}, {"text": "Foren", "correct": true, "because": "Praxiswissen"}, {"text": "Datenbanken", "correct": true, "because": "Strukturierte Infos"}, {"text": "Zeitschriften", "correct": false, "because": "Weniger aktuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Primärquellen sind verlässlicher. b) Social Media ist immer aktuell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Social Media kann ungenau sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Infos für ein Projekt suche?', 4, '[{"text": "Quellenverlässlichkeit", "correct": false, "because": "Wichtig für Genauigkeit"}, {"text": "Aktualität", "correct": false, "because": "Relevanz entscheidend"}, {"text": "Schriftfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Foren immer verlässlich sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können ungenau sein"}, {"text": "Ja", "correct": false, "because": "Prüfung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Quelle wähle ich für offizielle Software-Details?', 3, '[{"text": "Hersteller-Dokumentation", "correct": true, "because": "Primärquelle"}, {"text": "Blog", "correct": false, "because": "Sekundär"}, {"text": "Chat", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Recherche effektiv?', 5, '[{"text": "Verlässliche Quellen", "correct": true, "because": "Sichern Genauigkeit"}, {"text": "Strukturierte Suche", "correct": true, "because": "Spart Zeit"}, {"text": "Aktualität", "correct": true, "because": "Relevante Infos"}, {"text": "Schönes Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Suchmaschinen alles finden und b) Datenbanken veraltet sind. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Suchmaschinen begrenzt, Datenbanken aktuell"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Infos über ein Netzwerkproblem zu finden?', 4, '[{"text": "Fehlermeldung", "correct": false, "because": "Leitet Suche"}, {"text": "Dokumentation", "correct": false, "because": "Gibt Details"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind interne Wikis immer aktuell?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Pflege"}, {"text": "Ja", "correct": false, "because": "Kann veraltet sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen bei einer gezielten Suche?', 4, '[{"text": "Schlüsselwörter", "correct": true, "because": "Fokussieren Ergebnisse"}, {"text": "Filter", "correct": true, "because": "Reduzieren Rauschen"}, {"text": "Zufälliges Klicken", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Kollegen keine guten Quellen sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Praxiswissen nützlich"}, {"text": "Ja", "correct": false, "because": "Erfahrung hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Infos über eine Software suche?', 3, '[{"text": "Problemlösung", "correct": true, "because": "Löst aktuelle Aufgabe"}, {"text": "Designverbesserung", "correct": false, "because": "Sekundär"}, {"text": "Zeitersparnis", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenbanken bieten strukturierte Infos. b) Blogs sind immer verlässlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Blogs variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Quellenprüfung?', 4, '[{"text": "Verlässlichkeit sichern", "correct": true, "because": "Vermeidet Fehlinfos"}, {"text": "Schnelligkeit", "correct": false, "because": "Indirekt"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Stack Overflow immer die beste Quelle ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann ungenau sein"}, {"text": "Ja", "correct": false, "because": "Prüfung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gezielte Suche?', 5, '[{"text": "Zeitersparnis", "correct": true, "because": "Fokussiert Ergebnisse"}, {"text": "Genauigkeit", "correct": true, "because": "Relevante Infos"}, {"text": "Aktualität", "correct": true, "because": "Aktuelle Quellen"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Handbücher immer aktuell?', 3, '[{"text": "Nein", "correct": true, "because": "Können veralten"}, {"text": "Ja", "correct": false, "because": "Abhängig von Version"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für Netzwerkdaten?', 4, '[{"text": "Ping", "correct": true, "because": "Sammelt Erreichbarkeitsdaten"}, {"text": "Notepad", "correct": false, "because": "Nur Text"}, {"text": "Browser", "correct": false, "because": "Kein Netzwerktool"}]');
